/**
 * Extract prompt text from a version object shape.
 *
 * Handles two formats:
 * 1. String literal: returns the value as-is
 * 2. Arrow function: `(p) => \`...${p.tool.ToolName.output}...${p.input.fieldName}...\``
 *    Extracts the template literal body and converts expressions to mustache:
 *    - p.tool.ToolName.outputField  → {{ToolName.outputField}}
 *    - p.input.fieldName            → {{fieldname}} (normalized/lowercased)
 *
 * @returns The prompt string with mustache syntax, or empty string if not found
 */
function extractPromptValue(versionObj: ObjectShape): string {
    if (!versionObj.has('prompt')) {
        return ''
    }

    const promptShape = versionObj.get('prompt')

    // Case 1: String literal — use as-is
    if (promptShape?.isString()) {
        return promptShape.asString().getValue()
    }

    // Case 2: Arrow function — extract template literal and convert expressions
    if (promptShape instanceof ArrowFunctionShape) {
        const statements = promptShape.getStatements()
        const returnVal = promptShape.getReturnValue()
        // Support both block body (statements) and expression body (returnValue)
        const candidates = returnVal ? [...statements, returnVal] : statements
        for (const candidate of candidates) {
            if (candidate instanceof TemplateExpressionShape) {
                return convertTemplateToMustache(candidate)
            }
        }
        // Handle edge cases where the arrow function body is a plain string
        const singleExpr = statements[0] ?? returnVal
        if (singleExpr?.isString()) {
            return singleExpr.asString().getValue()
        }
    }

    // Fallback: try to get as string (may work for other shape types)
    try {
        return promptShape?.asString().getValue() ?? ''
    } catch {
        return ''
    }
}

/**
 * Convert a TemplateExpressionShape to a mustache-format prompt string.
 *
 * Processes each span's expression:
 * - PropertyAccessShape p.tool.ToolName.field           → {{ToolName.field}}
 * - PropertyAccessShape p.input.fieldName               → {{fieldname}} (normalized)
 * - PropertyAccessShape p.input.ACE.assigned_to.active  → {{ace.assigned_to.active}} (deep dot-walk)
 * - ElementAccessExpressionShape p.input['field name']  → {{field_name}} (bracket notation)
 * - ElementAccessExpressionShape p.input.ACE['field']   → {{ace.field}} (nested bracket)
 * - Fallback via getCode() for complex chains (e.g., p.input.jsonArray[0].name)
 */
function convertTemplateToMustache(template: TemplateExpressionShape): string {
    let result = template.getLiteralText()

    for (const span of template.getSpans()) {
        const expression = span.getExpression()
        let replacement = ''

        if (expression instanceof PropertyAccessShape) {
            const elements = expression.getElements()
            const elementNames = elements.map((e) => e.getName())

            // Pattern: p.tool.ToolName.outputField → {{ToolName.outputField}}
            if (elementNames.length >= 4 && elementNames[1] === 'tool') {
                const toolName = elementNames[2]
                const outputField = elementNames.slice(3).join('.')
                replacement = `{{${toolName}.${outputField}}}`
            }
            // Pattern: p.input.fieldName[.deepWalk...] → {{fieldname[.deepwalk...]}}
            else if (elementNames.length >= 3 && elementNames[1] === 'input') {
                const fieldName = elementNames[2]!
                const normalized = normalizeInputFieldName(fieldName)
                if (elementNames.length === 3) {
                    replacement = `{{${normalized}}}`
                } else {
                    // Deep dot-walk: p.input.ACE.assigned_to.active → {{ace.assigned_to.active}}
                    const rest = elementNames.slice(3).join('.')
                    replacement = `{{${normalized}.${rest}}}`
                }
            }
            // Unknown pattern — use code representation
            else {
                replacement = expression.getCode()
            }
        } else if (expression instanceof ElementAccessExpressionShape) {
            // Pattern: p.input['field name'] → {{field_name}} (normalized)
            // Handles bracket notation for input fields with spaces or special characters
            const callee = expression.getCallee() // e.g., "p.input"
            const arg = expression.getArg() // e.g., StringShape("field name")

            if (callee.endsWith('.input') && arg.isString()) {
                const fieldName = arg.asString().getValue()
                replacement = `{{${normalizeInputFieldName(fieldName)}}}`
            }
            // Pattern: p.input.ACE['assigned_to'] → {{ace.assigned_to}}
            // Pattern: p.input.jsonArray[0] → {{jsonarray.[0]}}
            else if (callee.includes('.input.')) {
                const match = callee.match(/\.input\.(.+)$/)
                if (match && match[1]) {
                    const chain = match[1]
                    if (arg.isString()) {
                        replacement = `{{${inputChainToTemplate(chain)}.${arg.asString().getValue()}}}`
                    } else {
                        // Non-string arg (e.g., numeric array index)
                        const argCode = arg.getCode()
                        replacement = `{{${inputChainToTemplate(chain)}.[${argCode}]}}`
                    }
                } else {
                    replacement = expression.getCode()
                }
            } else {
                // Unknown pattern — reconstruct bracket notation
                replacement = expression.getCode()
            }
        } else {
            // Fallback: detect input references from code representation
            // Handles complex chains like p.input.jsonArray[0].name
            const code = expression.getCode()
            const inputMatch = code?.match(/^[a-zA-Z_$]+\.input\.(.+)$/)
            if (inputMatch && inputMatch[1]) {
                replacement = `{{${inputChainToTemplate(inputMatch[1])}}}`
            } else {
                replacement = code || ''
            }
        }

        result += replacement + span.getLiteralText()
    }

    return result
}

/**
 * Validate that names contain only alphanumeric characters and spaces
 * @param str - Name to validate (skill name, attribute name, etc.)
 * @param diagnostics - Diagnostics object for error reporting
 * @param source - Source object for error location
 * @param nameType - Type of name being validated (e.g., 'Skill name', 'Attribute name')
 * @returns The original string (validation error will be reported via diagnostics)
 */
function validateName(
    str: string,
    diagnostics: Context['diagnostics'],
    source: Shape,
    nameType: string = 'Name'
): string {
    // Match AI Studio's validation: only alphanumeric characters and spaces
    const regex = /^[a-zA-Z0-9 ]+$/
    if (!regex.test(str)) {
        // Find and show specific invalid characters
        const invalidChars = str.match(/[^a-zA-Z0-9 ]/g)
        const invalidCharsStr = invalidChars ? [...new Set(invalidChars)].join(', ') : ''

        diagnostics.error(
            source,
            `${nameType} '${str}' contains invalid character(s): ${invalidCharsStr}. ` +
                `${nameType}s must contain only letters, numbers, and spaces. ` +
                `Please remove special characters, underscores, and punctuation.`
        )
    }
    return str
}

/**
 * Generate internal name from display name
 * Converts display names like 'Travel Destination' to 'travel_destination'
 * Matches AI Studio's convertAttributeLabelToName logic exactly
 * @param displayName - The user-friendly display name
 * @returns Clean internal name suitable for database storage
 */
function generateInternalName(displayName: string): string {
    // Convert to lowercase and replace one or more spaces with underscores
    return displayName.toLowerCase().trim().replace(/\s+/g, '_')
}

